// Reine Weiche: hier steht bewusst KEINE Systemlogik. Es wird nur geprueft, ob
// fuer das angefragte System ein Endpunkt in der Kunden-Config hinterlegt ist.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

const system = String(p.system || '').trim();
const endpunkte = (c.system_endpoints && typeof c.system_endpoints === 'object') ? c.system_endpoints : {};

let ziel = '';
let fehler = '';
if (!system) {
  fehler = 'system fehlt';
} else if (!Object.prototype.hasOwnProperty.call(endpunkte, system)) {
  fehler = 'no system configured';
} else {
  ziel = String(endpunkte[system] || '');
  // Nur HTTPS zulassen - der Wert kommt aus der Config, wird aber trotzdem geprueft.
  if (!/^https:\/\//.test(ziel)) fehler = 'no system configured';
}

// Die Abfrageparameter des Agenten werden als Ganzes weitergereicht, aber ohne
// Felder, die die Zuordnung ueberschreiben koennten.
const nutzlast = {};
Object.keys(p).forEach(k => {
  if (['system', 'kunde_id', 'config'].indexOf(k) === -1) nutzlast[k] = p[k];
});

return [{ json: Object.assign({}, e, {
  system: system, ziel: ziel, fehler: fehler,
  nutzlast: { kunde_id: String(e.kunde_id), system: system, params: nutzlast },
}) }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) return [{ json: antwort(false, {}, ktx.fehler) }];

const r = $input.first().json || {};
if (r.error) return [{ json: antwort(false, {}, 'system nicht erreichbar') }];
if (Number(r.statusCode) >= 400) {
  return [{ json: antwort(false, { code: Number(r.statusCode) }, 'system antwortet mit fehler') }];
}
const b = r.body;
// Das Kundensystem darf antworten wie es will - wir verpacken es unveraendert.
return [{ json: antwort(true, (b && typeof b === 'object' && !Array.isArray(b)) ? b : { ergebnis: b },
  'abfrage erfolgreich') }];
